void setAdj(string a, string b, vector<int> adj[], vector<int>& indeg){
    int as = a.size(), bs = b.size();
    int n = min(as,bs);
    for(int i=0; i<n; i++){
        if(a[i]!=b[i]){
            adj[a[i]-'a'].push_back(b[i]-'a');
            indeg[b[i]-'a']++;
            break;
        }
    }
}

